import{_ as a,o as s,c as i,ag as t}from"./chunks/framework.BGkQCay2.js";const u=JSON.parse('{"title":"Installation","description":"","frontmatter":{},"headers":[],"relativePath":"guide/installation.md","filePath":"guide/installation.md"}'),n={name:"guide/installation.md"};function l(r,e,o,h,p,d){return s(),i("div",null,[...e[0]||(e[0]=[t(`<h1 id="installation" tabindex="-1">Installation <a class="header-anchor" href="#installation" aria-label="Permalink to &quot;Installation&quot;">​</a></h1><p>The current documented workflow builds Vex from source. Prebuilt release packages and platform-specific distribution are tracked separately from the compiler source, so use the repository build when you need a version that matches the checked examples.</p><h2 id="requirements" tabindex="-1">Requirements <a class="header-anchor" href="#requirements" aria-label="Permalink to &quot;Requirements&quot;">​</a></h2><p>You need:</p><ul><li>a recent Rust toolchain with Cargo;</li><li>LLVM and Clang development tools required by the selected backend;</li><li>a native linker for your operating system;</li><li>Git to obtain the repository.</li></ul><p>The repository&#39;s workspace manifest is the authoritative source for compiler and tool versions. Vex is currently 0.4.0-rc.39 and remains pre-1.0.</p><h2 id="build-from-source" tabindex="-1">Build from source <a class="header-anchor" href="#build-from-source" aria-label="Permalink to &quot;Build from source&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clone</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://github.com/meftunca/vex_lang.git</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> vex_lang</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cargo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --release</span></span></code></pre></div><p>The release binary is target/release/vex. Confirm the build before using it:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">target/release/vex</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --version</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">target/release/vex</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --help</span></span></code></pre></div><p>For a faster edit-check cycle, use the debug build instead:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cargo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">target/debug/vex</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> lint</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> examples/01_basics/hello_world.vx</span></span></code></pre></div><h2 id="run-a-first-program" tabindex="-1">Run a first program <a class="header-anchor" href="#run-a-first-program" aria-label="Permalink to &quot;Run a first program&quot;">​</a></h2><p>Create hello.vx:</p><div class="language-vex vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">vex</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">fn</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> main</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">()</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> i32</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    $</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">println(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Hello, Vex!&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    return</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>Then check and run it:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">target/release/vex</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> lint</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> hello.vx</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">target/release/vex</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> hello.vx</span></span></code></pre></div><p>Use lint while writing code. It performs correctness and configured lint analysis without creating a final executable. Use run when you want the compiler to build a temporary executable and launch it.</p><div class="warning custom-block"><p class="custom-block-title">Current macOS runtime issue</p><p>On the current development line, source builds on macOS may fail while rebuilding the pure Vex runtime in the native I/O module. A successful check does not guarantee a successful run; see the repository-root report <code>VEX_COMPILER_ISSUES_2026-08-07.md</code> when this occurs.</p></div><h2 id="command-line-tools" tabindex="-1">Command-line tools <a class="header-anchor" href="#command-line-tools" aria-label="Permalink to &quot;Command-line tools&quot;">​</a></h2><p>The compiler currently exposes these high-level commands:</p><table tabindex="0"><thead><tr><th>Command</th><th>Purpose</th></tr></thead><tbody><tr><td><code>vex lint [target]</code></td><td>Run correctness analysis, semantic lints and verified fixes without code generation.</td></tr><tr><td><code>vex run &lt;file&gt;</code></td><td>Compile and run a source file.</td></tr><tr><td><code>vex compile &lt;file&gt;</code></td><td>Compile and link a persistent artifact.</td></tr><tr><td>vex build</td><td>Build a Vex package or project.</td></tr><tr><td>vex test</td><td>Discover and run Vex tests.</td></tr><tr><td>vex format</td><td>Format Vex source.</td></tr><tr><td>vex doc</td><td>Generate API documentation from Vex source.</td></tr><tr><td>vex view</td><td>Inspect compiler representations and analyses.</td></tr><tr><td>vex new / vex init</td><td>Create or initialize a project.</td></tr><tr><td>vex mod / vex workspace</td><td>Manage module and workspace workflows.</td></tr><tr><td>vex env / vex setup</td><td>Inspect or initialize the Vex environment.</td></tr></tbody></table><p>Run <code>vex &lt;command&gt; --help</code> for the options supported by the binary you built. The <a href="/docs/references/vex-cli-reference">CLI reference</a> describes the command surface in more detail.</p><h2 id="project-layout" tabindex="-1">Project layout <a class="header-anchor" href="#project-layout" aria-label="Permalink to &quot;Project layout&quot;">​</a></h2><p>A conventional project keeps the manifest and source tree separate:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>my-project/</span></span>
<span class="line"><span>├── vex.json</span></span>
<span class="line"><span>├── src/</span></span>
<span class="line"><span>│   └── main.vx</span></span>
<span class="line"><span>├── tests/</span></span>
<span class="line"><span>└── examples/</span></span></code></pre></div><p>The exact manifest fields depend on whether the project uses local modules, native artifacts, or package dependencies. Start with the <a href="/docs/references/vex-pm-reference">package manager reference</a> instead of copying an outdated manifest from a design note.</p><h2 id="editor-support" tabindex="-1">Editor support <a class="header-anchor" href="#editor-support" aria-label="Permalink to &quot;Editor support&quot;">​</a></h2><p>The repository includes an LSP implementation and a VS Code extension under editors/vscode. Build the LSP server with:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cargo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --release</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -p</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> vex-lsp</span></span></code></pre></div><p>The resulting binary is target/release/vex-lsp. Configure your editor to start it for .vx files. LSP capabilities and editor integration are evolving alongside the compiler, so treat advanced refactoring features as experimental.</p><h2 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h2><h3 id="llvm-or-clang-is-not-found" tabindex="-1">LLVM or Clang is not found <a class="header-anchor" href="#llvm-or-clang-is-not-found" aria-label="Permalink to &quot;LLVM or Clang is not found&quot;">​</a></h3><p>Install the development packages for your operating system and ensure the compiler can find them through the environment used by Cargo. On macOS, the Xcode Command Line Tools are usually required. On Linux, install the distribution&#39;s LLVM, Clang, and development packages.</p><h3 id="the-compiler-accepts-a-file-but-linking-fails" tabindex="-1">The compiler accepts a file but linking fails <a class="header-anchor" href="#the-compiler-accepts-a-file-but-linking-fails" aria-label="Permalink to &quot;The compiler accepts a file but linking fails&quot;">​</a></h3><p>check and compile exercise different parts of the toolchain. A successful check proves that the source passed parsing and semantic analysis; it does not prove that the target linker, runtime libraries, or native dependencies are available. Re-run with the full compiler output and record the target triple when reporting the problem.</p><h3 id="an-example-does-not-match-your-checkout" tabindex="-1">An example does not match your checkout <a class="header-anchor" href="#an-example-does-not-match-your-checkout" aria-label="Permalink to &quot;An example does not match your checkout&quot;">​</a></h3><p>Check the compiler version first:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">target/release/vex</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --version</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> rev-parse</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --short</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> HEAD</span></span></code></pre></div><p>The documentation site follows the repository&#39;s current development line. Pin both the compiler revision and the documentation revision in CI when reproducibility matters.</p><h2 id="next-steps" tabindex="-1">Next steps <a class="header-anchor" href="#next-steps" aria-label="Permalink to &quot;Next steps&quot;">​</a></h2><ul><li><a href="/docs/guide/introduction">Introduction</a></li><li><a href="/docs/guide/language-status">Language Status</a></li><li><a href="/docs/guide/basics/syntax">Syntax</a></li><li><a href="/docs/guide/tooling/testing">Testing</a></li><li><a href="/docs/references/vex-cli-reference">CLI Reference</a></li></ul>`,42)])])}const k=a(n,[["render",l]]);export{u as __pageData,k as default};
